node --input-type=module << 'EOF'
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
try {
  const validate = ajv.compile({
    type: 'object',
    properties: { location: { type: 'not-a-json-schema-type' } }
  });
  console.log('No error thrown, trying to validate...');
  const result = validate({location: 'test'});
  console.log('valid:', result, 'errors:', validate.errors);
} catch (e) {
  console.log('Compile error:', e.message);
}
EOF

node --input-type=module << 'EOF'
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});

// Test 1: missing required
const v1 = ajv.compile({ type: 'object', properties: { location: {type: 'string'} }, required: ['location'] });
v1({});
console.log('Missing required errors:', JSON.stringify(v1.errors?.map(e => ({path: e.instancePath, kw: e.keyword, msg: e.message, params: e.params}))));

// Test 2: wrong type
const v2 = ajv.compile({ type: 'object', properties: { ssn: {type: 'string'} }, required: ['ssn'] });
v2({ssn: 123456789});
console.log('Wrong type errors:', JSON.stringify(v2.errors?.map(e => ({path: e.instancePath, kw: e.keyword, msg: e.message, params: e.params}))));

// Test 3: extra properties pass through
const v3 = ajv.compile({ type: 'object', properties: { name: {type: 'string'} } });
const r3 = v3({name: 'Alice', extra: 'ignored'});
console.log('Extra props valid:', r3, 'errors:', v3.errors);
EOF
